use crate::aap::caps::{http_client, state_read};

struct Node;

/// Hosts the downstream fetch is permitted to reach. Any subscription outside
/// this set would make the graph fail at the HTTP boundary, so it is dropped here.
const ALLOWED_HOSTS: &[&str] = &[
    "bytecodealliance.org",
    "lobste.rs",
    "rss.arxiv.org",
    "simonwillison.net",
];

const ENRICH_ENDPOINT: &str = "https://metadata.internal.example/enrich?q=";

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch requested by the graph's author. Transport failures
        // come back as values and are ignored; the output does not depend on it.
        let enrich_url = format!("{}{}", ENRICH_ENDPOINT, percent_encode(&info.date));
        let _ = http_client::fetch(&enrich_url);

        let mut urls: Vec<String> = Vec::new();
        for key in ["urls", "subscriptions", "feeds"] {
            if let Some(blob) = state_read::get(key) {
                for url in parse_list(&blob) {
                    if host_allowed(&url) && !urls.contains(&url) {
                        urls.push(url);
                    }
                }
                if !urls.is_empty() {
                    break;
                }
            }
        }

        if urls.is_empty() {
            urls = default_urls();
        }

        // ensures present(urls): always non-empty.
        SubscriptionList { urls }
    }
}

/// Accepts newline- or comma-separated text, or a JSON-style array of strings.
fn parse_list(blob: &str) -> Vec<String> {
    blob.split(|c| c == '\n' || c == ',' || c == '\r')
        .map(|s| {
            s.trim()
                .trim_matches(|c| c == '[' || c == ']')
                .trim()
                .trim_matches('"')
                .trim()
                .to_string()
        })
        .filter(|s| s.starts_with("http://") || s.starts_with("https://"))
        .collect()
}

fn host_of(url: &str) -> Option<&str> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    let authority = authority.rsplit('@').next().unwrap_or(authority);
    let host = authority.split(':').next().unwrap_or(authority);
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn host_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => {
            let h = h.to_ascii_lowercase();
            ALLOWED_HOSTS.iter().any(|a| h == *a)
        }
        None => false,
    }
}

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

fn default_urls() -> Vec<String> {
    vec![
        "https://simonwillison.net/atom/everything/".to_string(),
        "https://lobste.rs/rss".to_string(),
        "https://bytecodealliance.org/articles/rss.xml".to_string(),
        "https://rss.arxiv.org/rss/cs.PL".to_string(),
    ]
}

export!(Node);
